/**
 * Model sample art (covers + icons generated by script/generate-model-samples.mjs),
 * with graceful fallbacks: models without a generated set keep the emoji-glyph and
 * gradient rendering. Each component probes the image and falls back on load error.
 */

import { useState } from "react";
import { modelCoverUrl, modelIconUrl, type Model } from "@/lib/catalog";
import { cn } from "@/lib/cn";

export const MODALITY_GLYPH: Record<Model["modality"], string> = {
  image: "🖼",
  video: "🎬",
  "3d": "🧊",
  world: "🌐",
  chat: "💬",
};

/** Cover art filling its (relative) parent; renders null when the model has no set. */
export function ModelCoverArt({ slug, className }: { slug: string; className?: string }) {
  const [ok, setOk] = useState(true);
  if (!ok) return null;
  return (
    <img
      src={modelCoverUrl(slug)}
      alt=""
      onError={() => setOk(false)}
      className={cn("absolute inset-0 h-full w-full object-cover", className)}
    />
  );
}

/** Small squared icon for table rows / compact lists; emoji glyph when there's no art. */
export function ModelIcon({ model, className }: { model: Model; className?: string }) {
  const [ok, setOk] = useState(true);
  if (!ok) return <span className={cn("text-lg", className)}>{MODALITY_GLYPH[model.modality]}</span>;
  return (
    <img
      src={modelIconUrl(model.slug)}
      alt=""
      onError={() => setOk(false)}
      className={cn("h-8 w-8 shrink-0 rounded-lg border border-border object-cover", className)}
    />
  );
}

/** Wide marquee banner for the model page header; renders null without art. */
export function ModelMarquee({ slug }: { slug: string }) {
  const [ok, setOk] = useState(true);
  if (!ok) return null;
  return (
    <div className="relative mb-8 overflow-hidden rounded-2xl border border-border">
      <img
        src={modelCoverUrl(slug)}
        alt=""
        onError={() => setOk(false)}
        className="h-56 w-full object-cover md:h-80"
      />
      <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/25 via-transparent to-transparent" />
    </div>
  );
}
